// src/api/LogsApi.js
import { get, post, del } from './HttpClient';

function buildQuery(params = {}) {
  const qs = new URLSearchParams();

  Object.entries(params).forEach(([k, v]) => {
    if (v === undefined || v === null) return;
    const s = String(v).trim();
    if (!s) return;
    qs.set(k, s);
  });

  const q = qs.toString();
  return q ? `?${q}` : '';
}

/**
 * GET /logs?page&size&from&to&keyword&aiLabel&eventType&sort
 */
export function fetchLogs(params = {}) {
  return get(`/logs${buildQuery(params)}`);
}

/**
 * GET /logs/recent?limit=50
 */
export function fetchRecentLogs(limit = 50) {
  return get(`/logs/recent?limit=${limit}`);
}

/**
 * DELETE /logs/{id}
 */
export function deleteLog(id) {
  return del(`/logs/${id}`);
}

/**
 * POST /logs/delete   body: { ids: [...] }
 */
export function deleteLogs(ids = []) {
  return post(`/logs/delete`, { ids });
}
